import type { Injector } from '@univerjs/core';
import { CustomDecorationType, ICommandService } from '@univerjs/core';
import * as DocsThreadComment from '@univerjs/docs-thread-comment';
import * as DocsFacade from '@univerjs/docs/facade';
import * as ThreadComment from '@univerjs/thread-comment';

export type IDocumentTextRangeCommentCreateOptions = Omit<
    DocsThreadComment.ICreateDocTextRangeCommentParams,
    'unitId' | 'range' | 'content'
>;

/** Comment methods added to a fixed document text range. */
export interface IFDocumentTextRangeThreadCommentMixin {
    /**
     * Creates a comment on this text range.
     * @param content Plain text or a Univer document body for rich comment content.
     * @param [options] Optional stable IDs, author, attachments, and creation time.
     * @returns {Promise<boolean>} `true` when the create command succeeds; otherwise, `false`.
     * @throws {TypeError} If the content is empty.
     * @example
     * ```ts
     * const range = univerAPI.getActiveDocument()?.getTextRange(0, 12);
     * await range?.createCommentAsync('Verify this introduction.', { id: 'review-intro' });
     * ```
     */
    createCommentAsync(
        content: ThreadComment.ThreadCommentContent,
        options?: IDocumentTextRangeCommentCreateOptions
    ): Promise<boolean>;
    /**
     * Returns locally loaded comments whose comment decorations overlap this text range.
     * @returns Matching comment threads. The returned anchors use `DOC_TEXT_RANGE`.
     * @example
     * ```ts
     * const range = univerAPI.getActiveDocument()?.getTextRange(0, 12);
     * const comments = range?.getComments() ?? [];
     * comments.forEach(({ root, children }) => console.log(root.id, children.length));
     * ```
     */
    getComments(): ThreadComment.IFacadeThreadCommentInfo[];
    /**
     * Synchronizes known document threads and returns comments whose decorations overlap this text range.
     * @returns {Promise<ThreadComment.IFacadeThreadCommentInfo[]>} A promise resolving to the synchronized matching comment threads.
     * @example
     * ```ts
     * const range = univerAPI.getActiveDocument()?.getTextRange(0, 12);
     * const comments = range ? await range.listCommentsAsync() : [];
     * console.log(comments.length);
     * ```
     */
    listCommentsAsync(): Promise<ThreadComment.IFacadeThreadCommentInfo[]>;
}

export class FDocumentTextRangeThreadCommentMixin extends DocsFacade.FDocumentTextRange implements IFDocumentTextRangeThreadCommentMixin {
    declare private _threadCommentCommandService: ICommandService;
    declare private _threadCommentFacadeService: ThreadComment.ThreadCommentFacadeService;

    override _initialize(injector: Injector): void {
        this._threadCommentCommandService = injector.get(ICommandService);
        let commentService: ThreadComment.ThreadCommentFacadeService | undefined;
        Object.defineProperty(this, '_threadCommentFacadeService', {
            get: () => commentService ??= injector.get(ThreadComment.ThreadCommentFacadeService),
        });
    }

    /** @inheritdoc */
    override createCommentAsync(
        content: ThreadComment.ThreadCommentContent,
        options: IDocumentTextRangeCommentCreateOptions = {}
    ): Promise<boolean> {
        return this._threadCommentCommandService.executeCommand(DocsThreadComment.CreateDocTextRangeCommentCommand.id, {
            ...options,
            unitId: this._document.getId(),
            range: { ...this.getRange(), collapsed: false },
            content,
        });
    }

    /** @inheritdoc */
    override getComments(): ThreadComment.IFacadeThreadCommentInfo[] {
        const range = this.getRange();
        const commentIds = this._getOverlappingCommentIds(range);
        return this._threadCommentFacadeService.getComments({
            unitIds: [this._document.getId()],
            subUnitIds: [DocsThreadComment.DEFAULT_DOC_SUBUNIT_ID],
            anchorKinds: [ThreadComment.ThreadCommentAnchorKind.DOC_TEXT_RANGE],
        }).filter((comment) => commentIds.has(comment.root.id));
    }

    /** @inheritdoc */
    override async listCommentsAsync(): Promise<ThreadComment.IFacadeThreadCommentInfo[]> {
        const range = this.getRange();
        const commentIds = this._getOverlappingCommentIds(range);
        const comments = await this._threadCommentFacadeService.listCommentsAsync({
            unitIds: [this._document.getId()],
            subUnitIds: [DocsThreadComment.DEFAULT_DOC_SUBUNIT_ID],
            anchorKinds: [ThreadComment.ThreadCommentAnchorKind.DOC_TEXT_RANGE],
        });
        return comments.filter((comment) => commentIds.has(comment.root.id));
    }

    private _getOverlappingCommentIds(range: DocsFacade.IFDocumentTextRange): Set<string> {
        const decorations = this._document.getBody(range.segmentId).customDecorations ?? [];
        return new Set(decorations.filter((decoration) => decoration.type === CustomDecorationType.COMMENT
            && decoration.startIndex < range.endOffset
            && decoration.endIndex >= range.startOffset).map((decoration) => decoration.id));
    }
}

DocsFacade.FDocumentTextRange.extend(FDocumentTextRangeThreadCommentMixin);

declare module '@univerjs/docs/facade' {
    interface FDocumentTextRange extends IFDocumentTextRangeThreadCommentMixin {}
}

//! What an uninstall may remove, and what it reports having removed.
//!
//! ADR-294's rule is that revocation and removal preserve export and forensic
//! access, so the default here keeps state and deleting it has to be asked for
//! by name.

use std::path::PathBuf;

use serde::Serialize;

/// What an uninstall is allowed to remove.
///
/// The default removes the runtime and keeps the state, which is the ADR-294
/// rule: revocation and removal preserve export and forensic access unless the
/// user asked for the state to go too.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct UninstallPolicy {
    /// Delete the state capsule. Only ever true because someone asked for it.
    pub remove_state: bool,
    /// Copy the sealed state here first. An export that fails aborts the
    /// uninstall, so state is never lost to a half-completed removal.
    pub export_state_to: Option<PathBuf>,
}

impl UninstallPolicy {
    /// Remove the runtime, keep the state.
    pub fn keep_state() -> Self {
        Self::default()
    }

    /// Export the state, then remove both.
    pub fn export_then_remove(dest: impl Into<PathBuf>) -> Self {
        Self {
            remove_state: true,
            export_state_to: Some(dest.into()),
        }
    }
}

/// What an uninstall actually did.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct UninstallOutcome {
    pub install_id: String,
    pub runtime_removed: bool,
    pub state_removed: bool,
    pub exported_to: Option<String>,
    pub exported_files: usize,
    /// Where state was left, when it was left.
    pub state_retained_at: Option<String>,
}

/// A copied state capsule.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct StateTransfer {
    pub base_identity: String,
    pub files: usize,
    pub bytes: u64,
    pub path: String,
}

# DotNetNuke.ContentSecurityPolicy

The `DotNetNuke.ContentSecurityPolicy` library provides a fluent API for building and emitting Content Security Policy (CSP) headers in DNN. The `IContentSecurityPolicy` interface is the main entry point to compose directives, manage sources, configure reporting, and generate final header strings.

## Interface: `IContentSecurityPolicy`
Namespace: `DotNetNuke.ContentSecurityPolicy`

### Properties
- **Nonce**: Cryptographically secure nonce value to use with inline script/style tags.
- **DefaultSource**: `SourceCspContributor` for `default-src`.
- **ScriptSource**: `SourceCspContributor` for `script-src`.
- **StyleSource**: `SourceCspContributor` for `style-src`.
- **ImgSource**: `SourceCspContributor` for `img-src`.
- **ConnectSource**: `SourceCspContributor` for `connect-src`.
- **FontSource**: `SourceCspContributor` for `font-src`.
- **ObjectSource**: `SourceCspContributor` for `object-src`.
- **MediaSource**: `SourceCspContributor` for `media-src`.
- **FrameSource**: `SourceCspContributor` for `frame-src`.
- **FrameAncestors**: `SourceCspContributor` for `frame-ancestors`.
- **FormAction**: `SourceCspContributor` for `form-action`.
- **BaseUriSource**: `SourceCspContributor` for `base-uri`.

### Methods
- **RemoveScriptSources(CspSourceType cspSourceType)**: Remove script sources of the specified type (e.g., `Inline`, `Self`, `Nonce`).
- **AddPluginTypes(string value)**: Add values for `plugin-types` (e.g., `application/pdf`).
- **AddSandboxDirective(string value)**: Add `sandbox` options (e.g., `allow-scripts allow-same-origin`).
- **AddFormAction(CspSourceType sourceType, string value)**: Add a `form-action` source.
- **AddFrameAncestors(CspSourceType sourceType, string value)**: Add a `frame-ancestors` source.
- **AddReportEndpoint(string name, string value)**: Add a named reporting endpoint.
- **AddReportTo(string value)**: Add a `report-to` group name to the policy.
- **AddHeaders(string cspHeader)**: Parse and merge a CSP header string; returns the same `IContentSecurityPolicy` for chaining.
- **GeneratePolicy()**: Build the `Content-Security-Policy` header value.
- **GenerateReportingEndpoints()**: Build the reporting header value(s).
- **UpgradeInsecureRequests()**: Add the `upgrade-insecure-requests` directive.

## Working with sources
Directive properties expose a `SourceCspContributor`, which supports adding/removing sources such as:
- `AddSelf()` → `'self'`
- `AddNone()` → `'none'`
- `AddInline()` → `'unsafe-inline'`
- `AddEval()` → `'unsafe-eval'`
- `AddStrictDynamic()` → `'strict-dynamic'`
- `AddNonce(string)` → `'nonce-<value>'`
- `AddHash(string)` → `'sha256-...'`, `'sha384-...'`, `'sha512-...'`
- `AddHost(string)` → `example.com`, `https://cdn.example.com`
- `AddScheme(string)` → `https:`, `data:`, `blob:`
- `RemoveSources(CspSourceType)` to remove by type

See: `CspSourceType.cs`, `CspSource.cs`, `SourceCspContributor.cs`.

## Usage examples

### Configure a baseline policy with a nonce
```csharp
using DotNetNuke.ContentSecurityPolicy;

public class CspExample
{
    private readonly IContentSecurityPolicy _csp;

    public CspExample(IContentSecurityPolicy csp)
    {
        _csp = csp;
    }

    public void Configure()
    {
        // Default baseline
        _csp.DefaultSource.AddSelf();
        _csp.ScriptSource.AddSelf().AddNonce(_csp.Nonce);
        _csp.StyleSource.AddSelf().AddNonce(_csp.Nonce);
        _csp.ImgSource.AddSelf().AddScheme("data:");

        // Lock down frames and forms
        _csp.FrameAncestors.AddNone();
        _csp.FormAction.AddSelf();

        // Reporting
        _csp.AddReportEndpoint("csp-endpoint", "/api/csp/report");
        _csp.AddReportTo("csp-endpoint");

        // Optionally upgrade insecure requests
        _csp.UpgradeInsecureRequests();

        // Generate header values
        var cspHeader = _csp.GeneratePolicy();
        var reportingHeader = _csp.GenerateReportingEndpoints();
        // Emit headers via your pipeline/middleware/module
    }
}
```

### Parse and merge an existing CSP header
```csharp
_csp.AddHeaders("default-src 'self'; img-src 'self' data:")
    .ScriptSource.AddNonce(_csp.Nonce);

var headerValue = _csp.GeneratePolicy();
```

### Remove an unsafe source
```csharp
_csp.RemoveScriptSources(CspSourceType.Inline);
```

## Notes
- Nonce: use `Nonce` in your inline tags: `<script nonce="{policy.Nonce}">`.
- Reporting: ensure your endpoint exists to accept violation reports.
- Parsing: `AddHeaders` is useful to import settings from configuration and extend them programmatically.

## Related files
- `ContentSecurityPolicy.cs`: policy composition and generation.
- `ContentSecurityPolicyParser.cs`: header string parsing.
- `CspDirectiveType.cs`, `CspDirectiveNameMapper.cs`: directive mapping.
- `CspSourceTypeNameMapper.cs`: maps source type names.
- `ReportingCspContributor.cs`, `ReportingEndpointContributor.cs`: reporting helpers.
- `DocumentCspContributor.cs`, `BaseCspContributor.cs`, `CspContributor.cs`: contributor abstractions.

# Content Security Policy Parser

This document describes the CSP header parsing functionality that has been added to the DotNetNuke.ContentSecurityPolicy library.

## Overview

The CSP parser allows you to parse existing Content Security Policy headers from strings into `ContentSecurityPolicy` objects that can be manipulated and regenerated.

## New Classes

### ContentSecurityPolicyParser

A static utility class that provides parsing functionality for CSP headers.

**Key Methods:**
- `Parse(string cspHeader)` - Parses a CSP header string and returns an `IContentSecurityPolicy` object
- `TryParse(string cspHeader, out IContentSecurityPolicy policy)` - Safely attempts to parse a CSP header

### Enhanced ContentSecurityPolicy

The main `ContentSecurityPolicy` class now includes static parsing methods:

**New Static Methods:**
- `Parse(string cspHeader)` - Static method that delegates to `ContentSecurityPolicyParser.Parse()`
- `TryParse(string cspHeader, out IContentSecurityPolicy policy)` - Static method that delegates to `ContentSecurityPolicyParser.TryParse()`

### Enhanced Mapping Classes

#### CspDirectiveNameMapper
- Added `GetDirectiveType(string directiveName)` - Convert directive names to enum values
- Added `TryGetDirectiveType(string directiveName, out CspDirectiveType directiveType)` - Safe conversion

#### CspSourceTypeNameMapper
- Added `GetSourceType(string sourceName)` - Convert source names to enum values
- Added `TryGetSourceType(string sourceName, out CspSourceType sourceType)` - Safe conversion
- Added helper methods: `IsQuotedKeyword()`, `IsNonceSource()`, `IsHashSource()`

## Usage Examples

### Basic Parsing

```csharp
// Parse a simple CSP header
var cspHeader = "default-src 'self'; script-src 'self' 'unsafe-inline'";
var policy = ContentSecurityPolicy.Parse(cspHeader);

// Access parsed directives
Console.WriteLine(policy.GeneratePolicy());
```

### Safe Parsing

```csharp
// Safely parse with error handling
var cspHeader = "default-src 'self'; invalid-directive something";
if (ContentSecurityPolicy.TryParse(cspHeader, out var policy))
{
    Console.WriteLine("Successfully parsed policy");
    Console.WriteLine(policy.GeneratePolicy());
}
else
{
    Console.WriteLine("Failed to parse CSP header");
}
```

### Complex Policy Parsing

```csharp
// Parse a complex CSP header
var complexHeader = "default-src 'self'; script-src 'self' 'nonce-abc123' https://cdn.example.com; style-src 'self' 'unsafe-inline' 'sha256-xyz789'; img-src 'self' data: https:; connect-src 'self' wss:; frame-ancestors 'none'; upgrade-insecure-requests";

var policy = ContentSecurityPolicy.Parse(complexHeader);

// Modify the parsed policy
policy.ScriptSource.AddHost("newcdn.example.com");
policy.StyleSource.AddHash("sha256-newHash123");

